const STORAGE_KEY = "relay-demo-state-v1";
const icon = (name, cls = "") => `<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const escapeHTML = value => String(value ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const defaults = {
  profile:{name:"Денис Гусев",email:"denis@example.com",phone:"+7 999 123-45-67",company:"Независимый разработчик",timezone:"Europe/Moscow",language:"Русский"},
  theme:"dark",notifications:true,weeklyReport:true,securityAlerts:true,compact:false,
  keys:[{id:"key_1",name:"Личный проект",prefix:"sk-proj-••••7f2a",created:"12 окт. 2026",lastUsed:"Сегодня, 14:32",scope:"Полный доступ"},{id:"key_2",name:"Прототип бота",prefix:"sk-proj-••••c91d",created:"28 сент. 2026",lastUsed:"Вчера, 18:07",scope:"Только чтение"}],
  devices:[{id:"device_1",name:"MacBook Pro",detail:"Chrome · Москва, Россия · Текущее устройство",last:"Активен сейчас",current:true},{id:"device_2",name:"iPhone 15",detail:"Приложение ChatGPT · Москва, Россия",last:"Сегодня, 09:14",current:false},{id:"device_3",name:"Рабочий компьютер",detail:"Firefox · Санкт-Петербург, Россия",last:"Вчера, 16:42",current:false}],
  notificationsRead:false,codexModel:"GPT-5-Codex",codexApproval:"Спрашивать при изменениях",codexAuto:true
};
let state = loadState();
function loadState(){try{return {...structuredClone(defaults),...JSON.parse(localStorage.getItem(STORAGE_KEY)||"{}")}}catch{return structuredClone(defaults)}}
function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));syncProfile()}
function syncProfile(){const p=state.profile;const initials=p.name.split(/\s+/).slice(0,2).map(x=>x[0]).join("").toUpperCase();["sidebar-avatar","topbar-avatar"].forEach(id=>{const el=document.getElementById(id);if(el)el.textContent=initials});const name=document.getElementById("sidebar-user-name"),email=document.getElementById("sidebar-user-email");if(name)name.textContent=p.name;if(email)email.textContent=p.email;document.documentElement.dataset.theme=state.theme;const color=state.theme==="dark"?"#08090b":"#f4f5f2";document.querySelector('meta[name="theme-color"]')?.setAttribute("content",color)}
const pages={overview:"Обзор",usage:"Использование",profile:"Профиль",subscription:"Тариф и оплата","api-keys":"API-ключи",codex:"Codex",security:"Безопасность",preferences:"Настройки"};
function currentPage(){const key=location.hash.replace(/^#\/?/,"").split("/")[0];return pages[key]?key:"overview"}
function go(page){location.hash=`/${page}`}
function toast(message,type="success"){const host=document.getElementById("toast-stack"),el=document.createElement("div");el.className=`toast ${type==="error"?"error":""}`;el.innerHTML=`${icon(type==="error"?"alert-circle":"check-circle")}<span>${escapeHTML(message)}</span>`;host.append(el);setTimeout(()=>{el.classList.add("out");setTimeout(()=>el.remove(),260)},3100)}
function pageHead(title,desc,eyebrow="Личный аккаунт",actions=""){return `<div class="page-head"><div><div class="eyebrow"><span class="eyebrow-line"></span>${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="head-actions">${actions}</div>`:""}</div>`}
function btn(label,action,iconName="",kind=""){return `<button class="btn ${kind}" data-action="${action}">${iconName?icon(iconName):""}${label}</button>`}
function pill(label,kind=""){return `<span class="pill ${kind}"><span class="pill-dot"></span>${label}</span>`}
function progress(percent,kind=""){return `<div class="progress ${kind}"><span style="width:${percent}%"></span></div>`}
function statCard(label,value,note,iconName,trend="",spark=true){return `<article class="card stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon">${icon(iconName)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${trend?`<span class="${trend.startsWith("+")?"trend-up":"trend-warn"}">${trend}</span>`:""}${note}</div>${spark?`<svg class="stat-spark" viewBox="0 0 62 28" aria-hidden="true"><path d="M1 22 C9 18 10 20 17 15 S25 20 33 12 S41 14 48 7 S55 9 61 2"/></svg>`:""}</article>`}
function usageChart(range="7d",large=false){const points=range==="30d"?"0,72 25,69 50,57 75,62 100,48 125,55 150,43 175,47 200,32 225,40 250,28 275,36 300,19 325,24 350,11 375,20 400,7":range==="24h"?"0,75 25,63 50,68 75,42 100,50 125,28 150,35 175,18 200,41 225,32 250,50 275,24 300,30 325,15 350,28 375,10 400,19":"0,69 36,56 72,63 108,34 144,47 180,23 216,38 252,17 288,31 324,12 360,22 400,8";const nums=points.split(" ").map(p=>p.split(",").map(Number));const line=nums.map((p,i)=>`${i?"L":"M"}${p[0]} ${p[1]}`).join(" ");const area=`${line} L400 100 L0 100 Z`;return `<div class="chart-wrap ${large?"large":""}"><svg viewBox="0 0 400 100" preserveAspectRatio="none" role="img" aria-label="График использования"><defs><linearGradient id="chart-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="var(--accent)" stop-opacity=".2"/><stop offset="100%" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs><path class="chart-grid" d="M0 25H400 M0 50H400 M0 75H400"/><path class="chart-area" d="${area}"/><path class="chart-line" d="${line}"/><circle class="chart-point" cx="400" cy="8" r="3"/></svg></div>`}
function render(){const page=currentPage(),view=document.getElementById("view");document.querySelectorAll("[data-nav]").forEach(a=>a.classList.toggle("active",a.dataset.nav===page));document.getElementById("crumb-current").textContent=pages[page];view.innerHTML=({overview:renderOverview,usage:renderUsage,profile:renderProfile,subscription:renderSubscription,"api-keys":renderKeys,codex:renderCodex,security:renderSecurity,preferences:renderPreferences}[page])();syncProfile();document.getElementById("sidebar").classList.remove("open");document.getElementById("sidebar-scrim").classList.remove("show")}
function renderOverview(){return ""}
function renderUsage(){return ""}
function renderProfile(){return ""}
function renderSubscription(){return ""}
function renderKeys(){return ""}
function renderCodex(){return ""}
function renderSecurity(){return ""}
function renderPreferences(){return ""}

