@@ -32,4 +32,15 @@
 function settingRow(title,description,key){return `<div class="setting-row"><div class="setting-copy"><strong>${title}</strong><span>${description}</span></div><button class="toggle" role="switch" aria-checked="${Boolean(state[key])}" data-toggle="${key}" aria-label="${title}"></button></div>`}
 function renderSecurity(){return `${pageHead("Безопасность","Контролируйте параметры защиты и активные сеансы демо-аккаунта.","Защита аккаунта",btn("Завершить другие сеансы","revoke-all","shield","btn-quiet"))}<div class="security-overview"><section class="card security-score"><span class="security-score-icon">${icon("shield")}</span><div><span class="plan-kicker">СОСТОЯНИЕ АККАУНТА</span><h2>Защита настроена</h2><p>Настройки применяются только в этом браузере и не влияют на реальные аккаунты.</p></div>${pill("Хорошо","pill-accent")}</section><section class="card settings-section"><h2>Оповещения безопасности</h2><p class="section-desc">Настройте напоминания в этом интерфейсе.</p>${settingRow("Уведомления о входах","Показывать уведомления о новых сеансах", "securityAlerts")}</section></div><section class="card security-devices"><div class="section-heading"><div><h2>Активные сеансы</h2><p>${state.devices.length} устройства · демо-данные</p></div>${icon("laptop")}</div>${state.devices.length?state.devices.map(device=>`<div class="device-row"><span class="device-icon">${icon(device.current?"laptop":"smartphone")}</span><div class="device-copy"><strong>${escapeHTML(device.name)}${device.current?pill("Это устройство","pill-accent"):""}</strong><span>${escapeHTML(device.detail)} · ${escapeHTML(device.last)}</span></div>${device.current?`<span class="subtle">Текущий</span>`:`<button class="btn btn-quiet btn-sm" data-action="revoke-device" data-id="${escapeHTML(device.id)}">Завершить</button>`}</div>`).join(""):`<div class="empty-state">Нет активных сеансов</div>`}</section><section class="card settings-section security-tips"><h2>Рекомендации</h2><div class="security-tip">${icon("check-circle")}<span><strong>Используйте уникальный пароль</strong><small>Не используйте один пароль в нескольких сервисах.</small></span></div><div class="security-tip">${icon("key")}<span><strong>Проверяйте API-ключи</strong><small>Удаляйте ключи, которыми больше не пользуетесь.</small></span><a class="text-link" href="#/api-keys">Открыть ${icon("arrow-right")}</a></div></section><div class="banner-note" style="margin-top:13px">${icon("alert-circle")}Relay — самостоятельный демо-интерфейс, не подключённый к OpenAI. Список устройств и события не являются реальными данными.</div>`}
 function renderPreferences(){return `${pageHead("Настройки","Персонализируйте интерфейс Relay в этом браузере.","Персонализация",btn("Сбросить настройки","reset-preferences","refresh","btn-quiet"))}<div class="settings-layout"><nav class="card settings-nav" aria-label="Разделы настроек"><button class="active" data-scroll="appearance">${icon("sun")}Внешний вид</button><button data-scroll="notifications-settings">${icon("bell")}Уведомления</button><button data-scroll="language-settings">${icon("globe")}Язык и регион</button></nav><div class="settings-content"><section class="card settings-section" id="appearance"><h2>Внешний вид</h2><p class="section-desc">Настройте отображение приложения.</p><div class="setting-row"><div class="setting-copy"><strong>Тема оформления</strong><span>Выберите комфортную цветовую схему</span></div><select class="inline-select" data-setting="theme"><option value="dark" ${state.theme==="dark"?"selected":""}>Тёмная</option><option value="light" ${state.theme==="light"?"selected":""}>Светлая</option></select></div>${settingRow("Компактный режим","Уменьшить отступы и плотнее разместить содержимое","compact")}</section><section class="card settings-section" id="notifications-settings"><h2>Уведомления</h2><p class="section-desc">Вы управляете только уведомлениями демо-интерфейса.</p>${settingRow("Уведомления в приложении","Показывать события в центре уведомлений","notifications")}${settingRow("Еженедельный отчёт","Напоминание о сводке активности","weeklyReport")}${settingRow("Оповещения безопасности","Уведомления о событиях защиты","securityAlerts")}</section><section class="card settings-section" id="language-settings"><h2>Язык и регион</h2><p class="section-desc">Локальные предпочтения отображения.</p><label class="field"><span class="field-label">Язык интерфейса</span><select class="inline-select" data-setting="profile.language"><option ${state.profile.language==="Русский"?"selected":""}>Русский</option><option ${state.profile.language==="English"?"selected":""}>English</option></select></label><label class="field" style="margin-top:13px"><span class="field-label">Часовой пояс</span><select class="inline-select" data-setting="profile.timezone"><option value="Europe/Moscow" ${state.profile.timezone==="Europe/Moscow"?"selected":""}>Москва (UTC+3)</option><option value="Europe/Kaliningrad" ${state.profile.timezone==="Europe/Kaliningrad"?"selected":""}>Калининград (UTC+2)</option><option value="Asia/Yekaterinburg" ${state.profile.timezone==="Asia/Yekaterinburg"?"selected":""}>Екатеринбург (UTC+5)</option><option value="Europe/London" ${state.profile.timezone==="Europe/London"?"selected":""}>Лондон</option></select></label></section><div class="settings-save-note">${icon("lock")}Настройки сохраняются локально в вашем браузере.</div></div></div>`}

+function openModal({title,description="",body="",wide=false,submit="Сохранить",cancel="Отмена",form=""}){const root=document.getElementById("modal-root");root.innerHTML=`<div class="modal-backdrop" data-modal-backdrop><section class="modal ${wide?"modal-wide":""}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${escapeHTML(title)}</h2>${description?`<p>${escapeHTML(description)}</p>`:""}</div><button class="modal-close" type="button" data-modal-close aria-label="Закрыть">${icon("x")}</button></header><form data-form="${escapeHTML(form)}"><div class="modal-body">${body}</div><footer class="modal-foot"><button type="button" class="btn" data-modal-close>${escapeHTML(cancel)}</button><button type="submit" class="btn btn-primary">${escapeHTML(submit)}</button></footer></form></section></div>`;root.querySelector("input,select,textarea")?.focus()}
+function closeModal(){document.getElementById("modal-root").innerHTML=""}
+function field(label,name,value,type="text",hint=""){return `<label class="field"><span class="field-label">${escapeHTML(label)}</span><input name="${escapeHTML(name)}" type="${type}" value="${escapeHTML(value)}" ${name==="email"?"required":""}>${hint?`<small class="field-hint">${escapeHTML(hint)}</small>`:""}</label>`}
+function showProfileForm(){const p=state.profile;openModal({title:"Редактировать профиль",description:"Изменения сохраняются только в этом браузере.",form:"profile",wide:true,body:`<div class="form-grid">${field("Полное имя","name",p.name)}${field("Электронная почта","email",p.email,"email")}${field("Телефон","phone",p.phone)}${field("Компания","company",p.company)}</div>`})}
+function showKeyForm(){openModal({title:"Создать демо-ключ",description:"Ключ будет создан локально и не получит доступ к API.",form:"key",body:`<label class="field"><span class="field-label">Название ключа</span><input name="name" required maxlength="40" placeholder="Например, Тестовый проект"></label><label class="field" style="margin-top:13px"><span class="field-label">Разрешения</span><select name="scope" class="inline-select"><option>Только чтение</option><option>Полный доступ</option></select></label><p class="field-hint" style="margin-top:12px">Секретное значение отображается один раз и не сохраняется.</p>`})}
+function showNotifications(){const panel=document.getElementById("notifications-panel");panel.innerHTML=`<div class="dropdown-title"><span>Уведомления</span><button class="text-link" data-action="mark-read">Отметить прочитанными</button></div><div class="notification-item"><span class="notification-icon">${icon("terminal")}</span><div><strong>Codex завершил задачу</strong><p>«Рефакторинг API» выполнен успешно.</p><time>12 минут назад</time></div></div><div class="notification-item"><span class="notification-icon">${icon("chart")}</span><div><strong>Еженедельная сводка готова</strong><p>Использовано 64% месячного лимита сообщений.</p><time>Сегодня</time></div></div><div class="notification-item"><span class="notification-icon">${icon("shield")}</span><div><strong>Сеансы в порядке</strong><p>Новых демо-событий безопасности нет.</p><time>Сегодня</time></div></div><div class="notification-foot"><span class="subtle">Уведомления — демонстрационные</span></div>`;panel.hidden=false;document.getElementById("notif-button").setAttribute("aria-expanded","true")}
+const paletteItems=[{label:"Обзор",page:"overview",icon:"home"},{label:"Использование",page:"usage",icon:"chart"},{label:"Профиль",page:"profile",icon:"user"},{label:"Тариф и оплата",page:"subscription",icon:"card"},{label:"API-ключи",page:"api-keys",icon:"key"},{label:"Codex",page:"codex",icon:"terminal"},{label:"Безопасность",page:"security",icon:"shield"},{label:"Настройки",page:"preferences",icon:"sliders"}];
+function drawPalette(query=""){const root=document.getElementById("palette-root"),matches=paletteItems.filter(x=>x.label.toLowerCase().includes(query.toLowerCase()));root.innerHTML=`<div class="palette-backdrop" data-palette-backdrop><section class="palette" role="dialog" aria-modal="true" aria-label="Поиск по аккаунту"><div class="palette-search">${icon("search")}<input type="search" placeholder="Перейти к разделу…" aria-label="Поиск" value="${escapeHTML(query)}"><kbd>ESC</kbd></div><p class="palette-label">Разделы</p><div class="palette-results">${matches.length?matches.map((x,i)=>`<button class="palette-result ${i===0?"selected":""}" data-go="${x.page}">${icon(x.icon)}<span>${x.label}</span><kbd>↵</kbd></button>`).join(""):`<div class="palette-empty">Ничего не найдено</div>`}</div></section></div>`;root.querySelector("input")?.focus()}
+function setSetting(key,value){const path=key.split(".");let target=state;for(const part of path.slice(0,-1))target=target[part];target[path.at(-1)]=value;save();if(key==="theme"||key==="compact")document.documentElement.classList.toggle("compact",Boolean(state.compact));if(key.startsWith("profile."))render();toast("Настройка сохранена")}
+function exportUsage(){const rows=[["Показатель","Значение"],["Всего запросов","1284"],["Обработано токенов","2400000"],["ChatGPT","862"],["Codex","286"],["API","136"]];const csv="\uFEFF"+rows.map(row=>row.map(cell=>`"${cell.replaceAll('"','""')}"`).join(";")).join("\n");const link=document.createElement("a");link.href=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));link.download="relay-usage-demo.csv";link.click();URL.revokeObjectURL(link.href);toast("Демо-отчёт сохранён")}
+function performAction(action,button){switch(action){case"toggle-sidebar":{const sidebar=document.getElementById("sidebar"),scrim=document.getElementById("sidebar-scrim");sidebar.classList.toggle("open");scrim.classList.toggle("show");break}case"open-palette":drawPalette();break;case"toggle-notifications":{const panel=document.getElementById("notifications-panel");if(panel.hidden)showNotifications();else{panel.hidden=true;document.getElementById("notif-button").setAttribute("aria-expanded","false")}break}case"mark-read":state.notificationsRead=true;save();document.getElementById("notif-dot").hidden=true;toast("Уведомления отмечены прочитанными");break;case"edit-profile":showProfileForm();break;case"preferences":go("preferences");break;case"create-key":showKeyForm();break;case"delete-key":{const key=state.keys.find(x=>x.id===button.dataset.id);if(!key)return;openModal({title:"Удалить демо-ключ?",description:`Ключ «${key.name}» будет удалён из локального списка.`,form:`delete-key:${key.id}`,submit:"Удалить",body:`<p class="field-hint">Это действие нельзя отменить.</p>`});break}case"revoke-device":{const device=state.devices.find(x=>x.id===button.dataset.id);if(!device)return;openModal({title:"Завершить сеанс?",description:`Демо-сеанс «${device.name}» будет удалён из списка.`,form:`revoke:${device.id}`,submit:"Завершить",body:`<p class="field-hint">Текущий сеанс останется активен.</p>`});break}case"revoke-all":openModal({title:"Завершить другие сеансы?",description:"Будут удалены все демо-сеансы, кроме текущего устройства.",form:"revoke-all",submit:"Завершить сеансы",body:`<p class="field-hint">Реальные устройства и аккаунты не затрагиваются.</p>`});break;case"export-usage":exportUsage();break;case"refresh":toast("Демо-данные обновлены");break;case"codex-task":toast("Демо-задача добавлена в очередь");break;case"codex-docs":openModal({title:"О Codex",description:"Помощник по разработке в демонстрационном интерфейсе Relay.",body:`<p class="field-hint">Эта страница не подключается к репозиториям и не запускает код. Настройки Codex сохраняются локально.</p>`,submit:"Понятно",cancel:"Закрыть",form:"info"});break;case"open-help":openModal({title:"Помощь Relay",description:"Демо-консоль управления аккаунтом.",body:`<p class="field-hint">Relay — самостоятельный демонстрационный интерфейс, не официальный продукт и не интеграция OpenAI. Все изменения хранятся только в этом браузере.</p>`,submit:"Понятно",cancel:"Закрыть",form:"info"});break;case"workspace-menu":toast("У вас одно демо-пространство");break;case"manage-plan":case"edit-payment":case"billing-history":openModal({title:action==="billing-history"?"История платежей":"Демо-режим оплаты",description:"Реальные платежи и изменения подписки отключены.",body:`<p class="field-hint">В Relay показаны только демонстрационные сведения. Управление планом, картой и историей платежей не связано с OpenAI.</p>`,submit:"Понятно",cancel:"Закрыть",form:"info"});break;case"cancel-subscription":openModal({title:"Отменить демо-подписку?",description:"Действие изменит только локальную демонстрацию.",form:"cancel-subscription",submit:"Отменить демо-план",body:`<p class="field-hint">Никакая реальная подписка не будет затронута.</p>`});break;case"select-plan":openModal({title:`План ${button.dataset.plan}`,description:"Выбор плана доступен только в демо-режиме.",form:"info",submit:"Понятно",cancel:"Закрыть",body:`<p class="field-hint">Планы и цены приведены для демонстрации; реальное оформление не выполняется.</p>`});break;case"reset-preferences":openModal({title:"Сбросить настройки?",description:"Тема, уведомления и Codex вернутся к значениям по умолчанию.",form:"reset-preferences",submit:"Сбросить",body:`<p class="field-hint">Профиль, ключи и список устройств сохранятся.</p>`});break}}

input.newString:
case"reset-preferences":openModal({title:"Сбросить настройки?",description:"Тема, уведомления и Codex вернутся к значениям по умолчанию.",form:"reset-preferences",submit:"Сбросить",body:`<p class="field-hint">Профиль, ключи и список устройств сохранятся.</p>`});break}}
function handleSubmit(event){const form=event.target.closest("form[data-form]");if(!form)return;event.preventDefault();const kind=form.dataset.form,data=new FormData(form);if(kind==="profile"){state.profile={...state.profile,name:String(data.get("name")||"").trim(),email:String(data.get("email")||"").trim(),phone:String(data.get("phone")||"").trim(),company:String(data.get("company")||"").trim()};save();closeModal();render();toast("Профиль обновлён");return}if(kind==="key"){const name=String(data.get("name")||"").trim();if(!name){form.elements.name.focus();return}const tail=Math.random().toString(36).slice(2,6);const key={id:`key_${Date.now()}`,name,prefix:`sk-demo-••••${tail}`,created:new Intl.DateTimeFormat("ru-RU",{day:"numeric",month:"short"}).format(new Date()),lastUsed:"Ещё не использовался",scope:String(data.get("scope"))};state.keys.unshift(key);save();render();openModal({title:"Демо-ключ создан",description:"Он сохранён только в локальном браузере и не имеет доступа к API.",body:`<div class="field"><span class="field-label">Название</span><strong>${escapeHTML(key.name)}</strong></div><div class="field" style="margin-top:13px"><span class="field-label">Маскированный идентификатор</span><code>${escapeHTML(key.prefix)}</code></div>`,submit:"Готово",cancel:"Закрыть",form:"info"});return}if(kind.startsWith("delete-key:")){const id=kind.slice("delete-key:".length);state.keys=state.keys.filter(x=>x.id!==id);save();closeModal();render();toast("Демо-ключ удалён");return}if(kind.startsWith("revoke:")){const id=kind.slice("revoke:".length);state.devices=state.devices.filter(x=>x.id!==id);save();closeModal();render();toast("Демо-сеанс завершён");return}if(kind==="revoke-all"){state.devices=state.devices.filter(x=>x.current);save();closeModal();render();toast("Другие демо-сеансы завершены");return}if(kind==="reset-preferences"){for(const key of ["theme","notifications","weeklyReport","securityAlerts","compact","codexModel","codexApproval","codexAuto"])state[key]=structuredClone(defaults[key]);save();closeModal();render();document.documentElement.classList.remove("compact");toast("Настройки сброшены");return}if(kind==="cancel-subscription"){closeModal();toast("Демо-подписка отмечена для отмены");return}closeModal()}
