const targets = await (await fetch('http://localhost:9222/json/list')).json();
const target = targets.find(x => x.type === 'page' && x.url.includes('localhost:3000'));
if (!target) throw new Error('Relay page not found');
const ws = new WebSocket(target.webSocketDebuggerUrl);
let nextId = 0;
const pending = new Map();
const errors = [];
ws.addEventListener('message', event => {
  const msg = JSON.parse(event.data);
  if (msg.method === 'Runtime.exceptionThrown') errors.push(msg.params.exceptionDetails.text);
  if (msg.id && pending.has(msg.id)) {
    const {resolve, reject} = pending.get(msg.id); pending.delete(msg.id);
    msg.error ? reject(new Error(msg.error.message)) : resolve(msg.result);
  }
});
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, {once:true}); ws.addEventListener('error', reject, {once:true}); });
const cdp = (method, params={}) => new Promise((resolve,reject) => { const id=++nextId; pending.set(id,{resolve,reject}); ws.send(JSON.stringify({id,method,params})); });
await cdp('Runtime.enable');
const evaluate = async expression => {
  const result = await cdp('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});
  if(result.exceptionDetails) throw new Error(result.exceptionDetails.exception?.description || result.exceptionDetails.text);
  return result.result.value;
};
const result = await evaluate(`(async()=>{
const assert=(ok,msg)=>{if(!ok)throw Error(msg)};
const click=(s)=>{const e=document.querySelector(s);assert(e,'missing '+s);e.click();return e};
const go=(page)=>{click('[data-nav="'+page+'"]');assert(location.hash.includes(page),'navigation '+page)};
const report=[];
assert(document.querySelector('#view').innerText.includes('рабочее пространство'),'initial overview'); report.push('overview rendered');
go('preferences');
assert(document.querySelectorAll('[data-setting]').length>0,'preference controls');
const setting=document.querySelector('[data-setting]');setting.click();
assert(document.querySelector('#toast-root').textContent.includes('Настройка сохранена'),'setting toast');report.push('settings interaction');
go('profile');click('[data-action="edit-profile"]');
const name=document.querySelector('[data-form="profile"] [name="name"]');name.value='Тестовый пользователь';
click('[data-form="profile"] button[type="submit"]');
assert(document.querySelector('#view').innerText.includes('Тестовый пользователь'),'profile saved');report.push('profile edit/save');
go('api-keys');click('[data-action="create-key"]');
const keyName=document.querySelector('[data-form="key"] [name="name"]');keyName.value='Проверочный ключ';
click('[data-form="key"] button[type="submit"]');
assert(document.querySelector('#modal-root').innerText.includes('Демо-ключ создан'),'key created');click('[data-modal-close]');
assert(document.querySelector('#view').innerText.includes('Проверочный ключ'),'key listed');report.push('API key create');
go('usage');
assert(document.querySelector('[data-range]'),'usage range control');click('[data-range="24h"]');
assert(document.querySelector('[data-chart-total]').textContent==='192','usage range updated');click('[data-action="export-usage"]');report.push('usage chart and export');
go('security');
assert(document.querySelector('[data-action="revoke-device"]'),'device revoke action');click('[data-action="revoke-device"]');click('[data-form^="revoke:"] button[type="submit"]');
assert(document.querySelectorAll('[data-action="revoke-device"]').length===1,'device removed');report.push('device session revoke');
click('[data-action="toggle-notifications"]');assert(!document.querySelector('#notifications-panel').hidden,'notifications opened');click('[data-action="mark-read"]');report.push('notifications read');
document.dispatchEvent(new KeyboardEvent('keydown',{key:'k',ctrlKey:true,bubbles:true}));
assert(document.querySelector('.palette-search input'),'search palette opened');
const input=document.querySelector('.palette-search input');input.value='проф';input.dispatchEvent(new Event('input',{bubbles:true}));assert(document.querySelector('.palette-result')?.textContent.includes('Профиль'),'search filter');click('.palette-result');assert(location.hash.includes('profile'),'search navigation');report.push('search and navigation');
await cdpNotNeeded();
return report;
})()`);
console.log('PASS:', result.join(' | '));
console.log('Browser exceptions:', errors.length ? errors.join(' | ') : 'none');
await cdp('Page.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});
const mobile = await evaluate(`(()=>{const b=document.querySelector('[data-action="toggle-sidebar"]');b.click();return {open:document.querySelector('#sidebar').classList.contains('open'),scrim:document.querySelector('#sidebar-scrim').classList.contains('show')}})()`);
console.log('Mobile menu:', JSON.stringify(mobile));
await cdp('Page.setDeviceMetricsOverride',{width:1280,height:900,deviceScaleFactor:1,mobile:false});
ws.close();
function cdpNotNeeded(){return Promise.resolve()}

